    const query = `
    SELECT 
      r.room_id,
      r.name,
      r.is_group,
      r.created_by,
      r.last_message_at,
      r.avatar_url,
      r.description,
      r.is_pinned,
      m.last_read_message_id,
      m.last_read_at,
      m.role,
      m.unread_count,
      COALESCE(
        json_agg(
          DISTINCT jsonb_build_object(
            'user_id', u.user_id,
            'name', u.full_name,
            'avatar_url', u.avatar_url
          )
        ) FILTER (WHERE u.user_id IS NOT NULL),
        '[]'
      ) AS members,
      (
        ARRAY_AGG(u.user_id) 
        FILTER (WHERE u.user_id != $1)
      )[1] AS partner_id,

      (
        ARRAY_AGG(u.full_name) 
        FILTER (WHERE u.user_id != $1)
      )[1] AS partner_name,

      (
        ARRAY_AGG(u.avatar_url) 
        FILTER (WHERE u.user_id != $1)
      )[1] AS partner_avatar,
      lm.content as last_message_content,
      lmu.full_name as last_message_sender_name,
      CASE 
        WHEN r.is_group = false THEN (
          ARRAY_AGG(u.full_name) FILTER (WHERE u.user_id != $1)
        )[1]
        ELSE r.name
      END AS display_name
    FROM chat_rooms r
    JOIN chat_room_members m 
      ON r.room_id = m.room_id
