  const [attachments, setAttachments] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    setCurrentUser(user);
  }, []);
  const [members, setMembers] = useState([]);
  const typingRef = useRef(null);
  const textareaRef = useRef(null);
  const fileInputRef = useRef(null);
  const imageInputRef = useRef(null);

  const store = useMessageStore();
  const { replyingToMessage, clearReply } = useChatUIStore();

  useEffect(() => {
    if (room?.members && room.members.length > 0) {
      const otherMembers = room.members.filter(m => m.user_id !== currentUser?.uid);
      setMembers(otherMembers);
    } else if (room?.project_id) {
      getProjectMembersAPI(room.project_id).then((data) => {
        setMembers(data || []);
      }).catch(() => setMembers([]));
    } else if (currentUser) {
      getUsersAPI().then((data) => {
        const otherUsers = (data || []).filter(u => u.user_id !== currentUser.uid);
        setMembers(otherUsers);
      }).catch(() => setMembers([]));
    }
  }, [room?.members, room?.project_id, currentUser]);

  const handleSendMessage = async () => {
    if (!message.trim() && attachments.length === 0) return;

    try {
      // Upload attachments first if any
      let uploadedAttachments = [];
      if (attachments.length > 0) {
        setUploading(true);
        for (const file of attachments) {
          if (file.url) {
            uploadedAttachments.push({
              attachmentUrl: file.url,
              fileType: file.type,
              fileName: file.name
            });
          } else {
            const res = await uploadFileAPI(file);
            uploadedAttachments.push({
              attachmentUrl: res.data?.file_url || res.file_url,
              fileType: file.type.startsWith('image/') ? 'image' : 'file',
              fileName: file.name
            });
          }
        }
        setUploading(false);
      }

      const messageType = uploadedAttachments.some(a => a.fileType === 'image') ? 'image' : 'text';

      const savedMessage = await emitSendMessage(
        room.room_id, 
        message.trim(), 
        replyingToMessage?.message_id || null,
        uploadedAttachments,
        messageType
      );
      store.addMessage(room.room_id, savedMessage);
      setMessage("");
      setAttachments([]);
      if (textareaRef.current) textareaRef.current.style.height = "auto";
      clearReply();
    } catch (err) {
      setUploading(false);
      console.error("Send message failed:", err.message);
    }
  };

  const handleFileSelect = async (e, isImage = false) => {
    const files = Array.from(e.target.files);
