    } catch (error) {
      console.error("Error updating task:", error);
      notificationService.error(error.response?.data?.message || "Failed to update task. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleFieldBlur = (field) => {
    const taskFieldMap = {
      title: "title",
