  if (task.status === "done") return "done";
  if (!task.due_date) return task.status || "todo";

  const now = new Date();
  const dueDate = new Date(task.due_date);

  if (dueDate < now && task.status !== "done") {
    return "overdue";
  }
  return task.status || "todo";
};

